<script setup lang="ts">
import {computed,nextTick,ref,watch,onBeforeUnmount} from 'vue';
import {ArrowLeft,ArrowRight,ChevronRight,PanelLeftClose,PanelLeftOpen,X,Files,FolderTree} from 'lucide-vue-next';
import ConfigurationCodeEditor from './ConfigurationCodeEditor.vue';
import ConfigurationFileTree from './ConfigurationFileTree.vue';
import ConfigurationTreeNode from './ConfigurationTreeNode.vue';
import {componentRoots,componentTests,pushLocation,type ConfigLocation} from '../configurationNavigation';
import {VueFlow} from '@vue-flow/core';
import {Background} from '@vue-flow/background';
import {Controls} from '@vue-flow/controls';
import {api} from '../api';
import {useWorkspaceDraft} from '../composables/useWorkspaceDraft';
import {useActionFeedback} from '../composables/useNotifications';
import DraftStatus from './DraftStatus.vue';
import {emptyConfiguration,configGraph,sourceDeclaration,scalarProperties,type ConfigProject,type Compilation,type Artifact,type ConfigReport,type ConfigPackage,type Span} from '../configuration';
const emit=defineEmits<{catalog:[];system:[any]}>();
const project=ref<ConfigProject>(emptyConfiguration()),report=ref<ConfigReport|null>(null),release=ref<ConfigPackage|null>(null);
const busy=ref(''),error=ref(''),notice=ref('');useActionFeedback('Configuration language',busy,notice,error);
const view=ref('Source'),file=ref('main.lce'),search=ref(''),selected=ref(''),node=ref(''),libraryOpen=ref(true),inspectorOpen=ref(true);
const compiled=ref<Compilation|null>(null),compiledStamp=ref(''),reportStamp=ref(''),renameTo=ref(''),newFile=ref('');
const renameOpen=ref(false),renameInput=ref<HTMLInputElement|null>(null);
const packageID=ref('local.configuration'),packageVersion=ref('1.0.0'),comparison=ref<any>(null),releases=ref<{id:string;version:string;digest:string}[]>([]);
const editor=ref<InstanceType<typeof ConfigurationCodeEditor>|null>(null),upload=ref<HTMLInputElement|null>(null),previousUpload=ref<HTMLInputElement|null>(null),folderUpload=ref<HTMLInputElement|null>(null);
const stamp=()=>JSON.stringify(project.value);const current=computed(()=>compiledStamp.value===stamp()&&!!compiled.value?.valid);
const artifact=computed(()=>current.value?compiled.value?.artifacts.find(a=>a.symbol===selected.value):undefined);
const stage=ref(''),manualLayout=ref(false);
const lastValid=ref<Compilation|null>(null),session=ref(0),explorer=ref('Components'),chain=ref<string[]>([]),tabs=ref<string[]>(['main.lce']);
const history=ref<ConfigLocation[]>([{file:'main.lce',symbol:'',chain:[],view:'Source'}]),historyIndex=ref(0);
const treeCompilation=computed(()=>current.value?compiled.value:lastValid.value);
const roots=computed(()=>componentRoots(treeCompilation.value));
const currentComponent=computed(()=>treeCompilation.value?.artifacts.find(a=>a.symbol===selected.value));
const breadcrumbs=computed(()=>chain.value.flatMap(s=>{const a=treeCompilation.value?.artifacts.find(a=>a.symbol===s);return a?[a]:[]}));
const selectedTests=computed(()=>currentComponent.value?componentTests(treeCompilation.value,currentComponent.value):[]);
const includeChildren=ref(true);
const createMode=ref(''),componentName=ref(''),valueType=ref('string'),extractPath=ref('');
const componentNameInput=ref<HTMLInputElement|null>(null);
let creationStamp='';
const scalarOperations=new Set(['identity','equal','less_than','less_or_equal','and','or','not','select','add','subtract','concat']);
const extractableNodes=computed<{id:string;op:string;path:string}[]>(()=>artifact.value?.kind==='behavior'?(artifact.value.body.behavior?.nodes||[]).flatMap((n:any,i:number)=>scalarOperations.has(n.op)?[{id:n.id,op:n.op,path:`behavior.nodes[${i}]`}]:[]):[]);
async function openCreation(mode:string){
 await action('Preparing component',async()=>{
  if(!current.value&&!await check(true)){error.value='Fix the source diagnostics before creating a component.';return;}
  createMode.value=mode;componentName.value='';creationStamp=stamp();
  extractPath.value=extractableNodes.value.find(n=>n.id===node.value)?.path||extractableNodes.value[0]?.path||'';
 });
 await nextTick();componentNameInput.value?.focus();
}
async function createComponent(){
 await action(createMode.value==='extract'?'Extracting reusable component':'Creating component',async()=>{
  if(creationStamp!==stamp())throw Error('The source changed while this form was open. Close and reopen it to use the current draft.');
  const a=artifact.value;
  const extra=createMode.value==='extract'?{file:a?.origin.file,declaration:a&&sourceDeclaration(a),path:extractPath.value}: {valueType:valueType.value};
  const result=await transform(createMode.value==='extract'?'extract':'component',{...extra,name:componentName.value.trim()});
  if(result)createMode.value='';
 });
}

const currentDiagnostics=computed(()=>compiledStamp.value===stamp()?compiled.value:null);
const recovery=useWorkspaceDraft('configuration-project-v1',{project,report,release,file,selected,chain,tabs,explorer,view});
function remember(){history.value=pushLocation(history.value,historyIndex.value,{file:file.value,symbol:selected.value,chain:chain.value,view:view.value});historyIndex.value=history.value.length-1;}
function openFile(name:string,record=true){if(!(name in project.value.files))return;createMode.value='';file.value=name;view.value='Source';if(!tabs.value.includes(name))tabs.value.push(name);if(record)remember();}
function navigateHistory(delta:number){const i=historyIndex.value+delta;if(i<0||i>=history.value.length)return;const n=history.value[i];historyIndex.value=i;selected.value=n.symbol;chain.value=[...n.chain];openFile(n.file,false);view.value=n.view;}
function activateFile(name:string){const c=treeCompilation.value;const a=c?.artifacts.find(a=>a.origin.file===name)||c?.artifacts.find(a=>componentTests(c,a).some(t=>t.origin.file===name));if(a&&selected.value!==a.symbol){selected.value=a.symbol;const index=chain.value.indexOf(a.symbol);chain.value=index>=0?chain.value.slice(0,index+1):[a.symbol];node.value='';stage.value='';}openFile(name);}
function closeTab(name:string){const i=tabs.value.indexOf(name);tabs.value=tabs.value.filter(f=>f!==name);if(!tabs.value.length)tabs.value=[project.value.entry];if(name===file.value)openFile(tabs.value[Math.max(0,i-1)]||tabs.value[0]);}
function resetNavigation(){createMode.value='';session.value++;lastValid.value=null;compiled.value=null;compiledStamp.value='';selected.value='';chain.value=[];tabs.value=[project.value.entry];file.value=project.value.entry;history.value=[];historyIndex.value=-1;remember();}
function changeSource(name:string,value:string){delete project.value.lock;project.value.files[name]=value;}
let compileTimer:ReturnType<typeof setTimeout>|undefined;
watch(()=>stamp(),()=>{clearTimeout(compileTimer);compileTimer=setTimeout(()=>{if(!busy.value)void check(true).catch(e=>{error.value=(e as Error).message})},900)});
onBeforeUnmount(()=>clearTimeout(compileTimer));
const stages=computed(()=>artifact.value?.kind==='workflow'?[...new Set((artifact.value.body.nodes||[]).map((n:any)=>(n.stage||'').split('/')[0]))].filter(Boolean) as string[]:[]);
const graph=computed(()=>artifact.value?configGraph(artifact.value,stage.value,manualLayout.value):{nodes:[],edges:[]});
const chosen=computed(()=>graph.value.nodes.find(n=>n.id===node.value));
const properties=computed(()=>artifact.value?scalarProperties(chosen.value?.data.value||artifact.value.body):[]);
const declarations=computed(()=>compiled.value?.documents.find(d=>d.file===file.value)?.declarations||[]);
const files=computed(()=>Object.keys(project.value.files).sort().filter(f=>f.toLowerCase().includes(search.value.toLowerCase())));

watch(()=>Object.keys(project.value.files).join('|'),()=>{if(!(file.value in project.value.files))file.value=project.value.entry;tabs.value=tabs.value.filter(f=>f in project.value.files);if(!tabs.value.includes(file.value))tabs.value.push(file.value);});
watch(()=>stamp(),()=>{notice.value='';});
async function action(label:string,fn:()=>Promise<unknown>){if(busy.value)return;busy.value=label;error.value='';notice.value='';try{await recovery.ready;await fn();}catch(e){error.value=(e as Error).message;}finally{busy.value='';}}
async function check(quiet=false){const snapshot=stamp();const result=await api<Compilation>('/configuration/compile','POST',{project:JSON.parse(snapshot)});if(snapshot!==stamp()){if(!quiet)notice.value='Source changed during compilation. Compile the current draft.';return false};compiled.value=result;compiledStamp.value=snapshot;if(!result.valid){if(!quiet)notice.value=`${result.diagnostics.length} diagnostics. Select one to fix its source.`;return false};lastValid.value=result;if(!result.artifacts.some(a=>a.symbol===selected.value)){selected.value=componentRoots(result)[0]?.symbol||'';chain.value=selected.value?[selected.value]:[];}if(!quiet)notice.value=`${result.artifacts.length} artifacts · ${result.experiments.length} experiments`;return true;}
async function loadExample(template='inspection'){await action('Loading example',async()=>{project.value=await api<ConfigProject>('/configuration/example'+(template==='hierarchy'?'?template=hierarchy':''));resetNavigation();report.value=null;release.value=null;view.value='Source';await check();});}
async function run(all=false){await action(all?'Running all experiments':'Running component testbench',async()=>{if(!await check(true))return;const snapshot=stamp();const a=artifact.value;const scope=!all&&a?{target:{kind:a.kind,id:a.id,version:a.version,digest:a.digest},descendants:includeChildren.value}:undefined;const r=await api<ConfigReport>('/configuration/run','POST',{project:JSON.parse(snapshot),scope});report.value=r;reportStamp.value=snapshot;view.value='Testbench';notice.value=r.passed?`${r.cases.length} experiments passed`:'Some experiments failed. Inspect the independent expectations below.';});}
async function transform(kind:string,extra:Record<string,unknown>={}){if(!current.value&&!await check(true))return;const snapshot=stamp();const r=await api<{project:ConfigProject;compilation:Compilation;paths?:Record<string,string>}>('/configuration/'+kind,'POST',{project:JSON.parse(snapshot),expectedHash:compiled.value!.sourceHash,file:file.value,...extra});if(snapshot!==stamp()){notice.value='The draft changed while preparing this edit. Your newer edits were kept.';return};const prior=artifact.value,priorCompilation=lastValid.value;project.value=r.project;compiled.value=r.compilation;compiledStamp.value=stamp();if(r.compilation.valid)lastValid.value=r.compilation;if(r.paths&&kind==='organize'){const nextFile=r.paths[file.value]||r.project.entry;tabs.value=tabs.value.map(f=>r.paths?.[f]||f);history.value=[];historyIndex.value=-1;file.value=nextFile;}if(prior){selected.value=r.compilation.artifacts.find(a=>a.kind===prior.kind&&a.id===prior.id&&a.version===prior.version)?.symbol||selected.value;}if(r.paths?.testbench&&!r.paths.component)openFile(r.paths.testbench);chain.value=chain.value.map(s=>{const old=priorCompilation?.artifacts.find(a=>a.symbol===s);return r.compilation.artifacts.find(a=>a.kind===old?.kind&&a.id===old?.id&&a.version===old?.version)?.symbol||s}).filter(s=>r.compilation.artifacts.some(a=>a.symbol===s));if(selected.value&&!chain.value.includes(selected.value))chain.value=[selected.value];if(r.paths?.component){const child=r.compilation.artifacts.find(a=>a.origin.file===r.paths!.component);if(child){chain.value=kind==='extract'?[...chain.value,child.symbol]:[child.symbol];selected.value=child.symbol;node.value='';openFile(r.paths.component);}}remember();notice.value=r.paths?.component?'Component and testbench created. Supply scenario inputs and independent expectations in its testbench.':r.compilation.valid?'Source and graph updated together':'Draft updated; fix the highlighted diagnostics before executing.';return r;}
async function patch(path:string,value:unknown){if(!artifact.value)return;const a=artifact.value;await action('Updating configuration property',()=>transform('patch',{file:a.origin.file,declaration:sourceDeclaration(a),path,value}));}
async function moveNode(event:any){if(!artifact.value||!event.node?.data?.path)return;await patch(event.node.data.path+'.position',{x:Math.round(event.node.position.x),y:Math.round(event.node.position.y)});}
function fieldValue(event:Event,type:string){const e=event.target as HTMLInputElement;return type==='boolean'?e.checked:type==='number'?(e.value===''?null:Number(e.value)):e.value;}
function fieldPath(path:string){return chosen.value?chosen.value.data.path+'.'+path:path;}
async function go(span:Span){activateFile(span.file);await nextTick();await editor.value?.reveal(span);}
async function definition(){await editor.value?.definition();}
async function startRename(name:string,offset:number){const a=compiled.value?.artifacts.find(a=>a.origin.file===name&&offset>=a.origin.start&&offset<=a.origin.end);if(!a){error.value='Place the cursor inside an artifact declaration to rename it.';return}selected.value=a.symbol;renameOpen.value=true;await nextTick();renameInput.value?.focus();}
function complete(){editor.value?.suggest();}
async function chooseSymbol(symbol:string,path:string[],span?:Span){const a=treeCompilation.value?.artifacts.find(a=>a.symbol===symbol);if(!a)return;createMode.value='';selected.value=symbol;chain.value=[...path];node.value='';stage.value='';openFile(span?.file||a.origin.file);if(span){await nextTick();await editor.value?.reveal(span);}}
async function createTestbench(symbol:string,path:string[]){await chooseSymbol(symbol,path);await action('Creating testbench',()=>transform('testbench',{name:symbol}));}
function addFile(){let name=newFile.value.trim();if(!/^[a-zA-Z0-9_/-]+\.lce$/.test(name)||name.includes('..')||name.startsWith('/')||project.value.files[name]){error.value='Use a new relative .lce filename.';return};delete project.value.lock;project.value.files[name]=`language "1.0";\nmodule "local.${name.replace(/[^a-zA-Z0-9]/g,'_')}" version "1.0.0";\n`;openFile(name);newFile.value='';view.value='Source';notice.value='Module created. Import it from the entry file to include its declarations.';}
function download(name:string,value:unknown){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);}
async function importFile(event:Event,compare=false){const input=event.target as HTMLInputElement,files=Array.from(input.files||[]).filter(f=>!f.webkitRelativePath||f.name.endsWith('.lce')),f=files[0];input.value='';if(!f)return;await action('Importing configuration',async()=>{if(files.reduce((n,f)=>n+f.size,0)>32*1024*1024)throw Error('Import exceeds 32 MiB');const text=await f.text();if(compare){if(!release.value)throw Error('Build or open a package first');comparison.value=await api('/configuration/compare','POST',{previous:JSON.parse(text),package:release.value});view.value='Packages';return};if(f.name.endsWith('.lce')){if(/^\s*(?:--[^\n]*\n\s*)*language\s+"1\.0"/i.test(text)){const sources:Record<string,string>={};for(const module of files){const name=module.webkitRelativePath?module.webkitRelativePath.split('/').slice(1).join('/'):module.name;if(!name.endsWith('.lce')||sources[name])throw Error('Select a project folder to retain nested module paths.');sources[name]=await module.text();}project.value={language:'1.0',entry:sources['test-suite.lce']?'test-suite.lce':sources['main.lce']?'main.lce':Object.keys(sources)[0],files:sources};}else{if(files.length!==1)throw Error('Migrate one legacy component at a time.');project.value=await api<ConfigProject>('/configuration/migrate','POST',{source:text});}release.value=null;report.value=null;}else{const data=JSON.parse(text);if(data.project&&data.digest){await api('/configuration/verify','POST',{package:data});release.value=data;project.value=data.project;report.value=data.report||null;reportStamp.value=stamp();}else{const check=await api<Compilation>('/configuration/compile','POST',{project:data});if(!check.valid)throw Error(check.diagnostics.map(d=>`${d.file}:${d.line} ${d.message}`).join('\n'));project.value=data;release.value=null;report.value=null;}}resetNavigation();await check();});}
async function pack(){await action('Building portable package',async()=>{if(!await check(true))return;const snapshot=stamp();const p=await api<ConfigPackage>('/configuration/pack','POST',{project:JSON.parse(snapshot),id:packageID.value,version:packageVersion.value,test:compiled.value!.experiments.length>0});release.value=p;report.value=p.report||null;reportStamp.value=snapshot;view.value='Packages';notice.value='Package contains source, exact locks, compiled artifacts and test evidence.';});}
async function install(){if(!release.value)return;await action('Installing immutable package',async()=>{const r=await api<{installed:number;existing:number}>('/configuration/install','POST',{package:release.value});emit('catalog');notice.value=`Installed ${r.installed} artifacts; ${r.existing} exact versions already present. Package saved to PostgreSQL.`;await listReleases();});}
async function listReleases(){releases.value=await api('/configuration/packages');}
async function openRelease(id:string,version:string){await action('Opening installed package',async()=>{const p=await api<ConfigPackage>(`/configuration/package?id=${encodeURIComponent(id)}&version=${encodeURIComponent(version)}`);release.value=p;project.value=p.project;report.value=p.report||null;resetNavigation();reportStamp.value=stamp();await check();});}
async function replay(){if(!release.value)return;await action('Reproducing packaged evidence',async()=>{const r=await api<ConfigReport>('/configuration/replay','POST',{package:release.value});report.value=r;view.value='Testbench';notice.value='Fresh execution exactly matches the packaged evidence.';});}
function selectNode(n:any){if(n.data?.stage!==undefined){stage.value=n.data.stage||'*';node.value='';}else node.value=n.id;}
function openSystem(a:Artifact){emit('system',JSON.parse(JSON.stringify(a.body)));}
</script>
<template>
<section class="configuration-studio" :aria-busy="!!busy" :inert="recovery.status.value==='loading'">
 <div class="configuration-toolbar"><strong>Configuration Language 1.0</strong><button :disabled="!!busy" @click="loadExample()">Inspection example</button><button :disabled="!!busy" @click="loadExample('hierarchy')">Nested component example</button><button :disabled="!!busy" @click="upload?.click()">Import / migrate</button><button :disabled="!!busy" @click="folderUpload?.click()">Import folder</button><button @click="download('configuration-project.json',project)">Export source</button><button :disabled="!!busy" @click="action('Compiling configuration',()=>check())">Compile</button><button :disabled="!!busy" @click="run(true)">Run all tests</button><button :disabled="!!busy" @click="pack">Build package</button><button :disabled="!!busy" @click="action('Organizing component folders',()=>transform('organize'))">Organize folders</button><button :aria-expanded="libraryOpen" @click="libraryOpen=!libraryOpen">{{libraryOpen?'Hide':'Show'}} explorer</button><button :aria-expanded="inspectorOpen" @click="inspectorOpen=!inspectorOpen">{{inspectorOpen?'Hide':'Show'}} inspector</button></div>
 <DraftStatus :draft="recovery"/>
 <p v-if="busy||notice" role="status">{{busy||notice}}</p><p v-if="error" role="alert" class="config-error">{{error}}</p>
 <nav class="config-views" aria-label="Configuration views"><button v-for="v in ['Source','Canvas','Testbench','Packages']" :key="v" :aria-current="view===v?'page':undefined" @click="view=v">{{v}}</button></nav>
 <div class="configuration-layout" :class="{'no-library':!libraryOpen}">
  <aside v-if="libraryOpen" class="configuration-library">
   <div class="explorer-heading"><strong>EXPLORER</strong><button title="Collapse explorer" aria-label="Collapse explorer" @click="libraryOpen=false"><PanelLeftClose :size="16"/></button></div>
   <nav class="explorer-tabs" aria-label="Explorer mode"><button :aria-pressed="explorer==='Components'" @click="explorer='Components'"><FolderTree :size="14"/>Components</button><button :aria-pressed="explorer==='Files'" @click="explorer='Files'"><Files :size="14"/>Files</button></nav>
   <button class="new-component" :disabled="!!busy" @click="openCreation('component')">+ New component</button>
   <input v-model="search" aria-label="Search explorer" placeholder="Search components or files…"/>
   <template v-if="explorer==='Components'"><p v-if="!current&&lastValid" class="muted">Last valid structure · current draft is being checked.</p><ConfigurationTreeNode v-for="a in roots" :key="a.symbol" :artifact="a" :compilation="treeCompilation!" :chain="[a.symbol]" :active="selected" :active-chain="chain" :query="search" @open="chooseSymbol" @create="createTestbench"/><p v-if="!roots.length" class="muted">Create your first component or open the nested component example. Each component will have its own source and testbench.</p><p class="muted">Each level owns its source and testbench. Shared references reuse one definition.</p></template>
   <template v-else><ConfigurationFileTree :files="files" :active="file" :entry="project.entry" @open="activateFile"/><div class="add-file"><input v-model="newFile" aria-label="New module filename" placeholder="components/name/component.lce"/><button :disabled="!!busy" @click="addFile">Add file</button></div></template>
  </aside>
  <main class="configuration-main">
   <form v-if="createMode" class="component-create" aria-label="Component creation" @submit.prevent="createComponent" @keydown.esc="createMode=''">
    <div class="create-heading"><strong>{{createMode==='extract'?'Extract reusable subcomponent':'New reusable component'}}</strong><button type="button" aria-label="Close component creation" @click="createMode=''">Close</button></div>
    <p v-if="createMode==='extract'">Move a scalar primitive from {{artifact?.body.name}} into a child component. Its typed inputs, result and parent bindings are retained. Trace paths and invocation counts change; rerun the parent tests.</p>
    <p v-else>Create a small identity starter with its own source and testbench. It is added as a workspace root; edit its behavior to match your design.</p>
    <div class="create-fields"><label>Component symbol <span aria-hidden="true">*</span><input ref="componentNameInput" v-model="componentName" aria-label="Component symbol" required pattern="[A-Za-z][A-Za-z0-9_]{0,47}" maxlength="48" placeholder="TicketSelection" :disabled="!!busy"/></label>
     <label v-if="createMode==='component'">Starter value type<select v-model="valueType" aria-label="Starter value type" :disabled="!!busy"><option value="string">String</option><option value="integer">Integer</option><option value="boolean">Boolean</option></select></label>
     <label v-else>Primitive to extract<select v-model="extractPath" aria-label="Primitive to extract" :disabled="!!busy"><option v-for="n in extractableNodes" :key="n.path" :value="n.path">{{n.id}} · {{n.op}}</option></select></label>
     <button type="submit" :disabled="!!busy||!componentName.trim()||(createMode==='extract'&&!extractPath)">{{createMode==='extract'?'Extract component':'Create component'}}</button>
    </div>
    <p class="muted">The new testbench contains TODOs and will fail until you supply scenario inputs and independent expectations. Use letters, digits and underscores for the symbol, starting with a letter.</p>
   </form>
   <nav class="config-breadcrumbs" aria-label="Component location"><button :disabled="historyIndex<=0" title="Back" aria-label="Back" @click="navigateHistory(-1)"><ArrowLeft :size="15"/></button><button :disabled="historyIndex>=history.length-1" title="Forward" aria-label="Forward" @click="navigateHistory(1)"><ArrowRight :size="15"/></button><button v-if="!libraryOpen" title="Show explorer" aria-label="Show explorer" @click="libraryOpen=true"><PanelLeftOpen :size="15"/></button><button @click="openFile(project.entry)">Workspace</button><template v-for="(a,i) in breadcrumbs" :key="i"><ChevronRight :size="12"/><button @click="chooseSymbol(a.symbol,chain.slice(0,i+1))">{{a.body.name||a.id}}</button></template></nav>
   <div v-show="view==='Source'" class="source-pane">
    <div class="config-file-tabs" aria-label="Open files"><div v-for="f in tabs.filter(f=>f in project.files)" :key="f" :class="{active:f===file}" class="config-file-tab"><button :title="f" :aria-pressed="f===file" @click="activateFile(f)">{{f.split('/').slice(-2).join('/')}}</button><button :aria-label="'Close '+f" @click="closeTab(f)"><X :size="12"/></button></div></div>
    <div class="source-actions"><code class="active-path">{{file}}</code><button :disabled="!!busy" @click="action('Formatting source',()=>transform('format'))">Format</button><button :disabled="!!busy" @click="definition">Go to definition</button><button :disabled="!!busy" @click="complete">Suggestions</button><button v-if="extractableNodes.length" :disabled="!!busy" @click="openCreation('extract')">Extract primitive…</button><select aria-label="Jump to declaration" @change="go(declarations[Number(($event.target as HTMLSelectElement).value)].nameSpan)"><option disabled selected>Declarations</option><option v-for="(d,i) in declarations" :key="d.name" :value="i">{{d.kind}} {{d.name}}</option></select></div>
    <ConfigurationCodeEditor :key="session" ref="editor" :project="project" :file="file" :compilation="currentDiagnostics" :read-only="!!busy" :session="session" @change="changeSource" @navigate="go" @format="action('Formatting source',()=>transform('format'))" @rename="startRename" @error="error=$event"/>
    <details class="rename-details" :open="renameOpen"><summary>Rename a declaration safely</summary><div class="rename-bar"><select v-model="selected" aria-label="Artifact to rename"><option v-for="a in compiled?.artifacts" :key="a.symbol" :value="a.symbol">{{sourceDeclaration(a)}}</option></select><input ref="renameInput" v-model="renameTo" aria-label="New symbol name" placeholder="New symbol name"/><button :disabled="!!busy||!artifact||!renameTo" @click="action('Renaming symbol',()=>transform('rename',{file:artifact!.origin.file,declaration:sourceDeclaration(artifact!),name:renameTo}))">Rename symbol safely</button></div></details>
    <p class="muted">Ctrl/Cmd+Space suggestions · F12 definition · F2 rename · Shift+Alt+F format · Ctrl/Cmd+F find · Ctrl/Cmd+H replace. Source edits autosave and refresh diagnostics.</p>
   </div>
   <template v-if="view==='Canvas'"><p v-if="!current">Compile the current source to inspect its graph. Invalid source remains saved as a draft.</p><template v-else-if="artifact"><div class="canvas-heading"><strong>{{artifact.body.name}} · {{artifact.kind}}</strong><button @click="node=''">Artifact properties</button><select v-if="stages.length" v-model="stage" aria-label="Workflow stage" @change="node=''"><option value="">Stage overview</option><option value="*">All steps</option><option v-for="s in stages" :key="s" :value="s">{{s}}</option></select><label v-if="artifact.kind==='workflow'"><input v-model="manualLayout" type="checkbox"/>Manual positions</label><button @click="go(artifact.origin)">Open source</button><button v-if="artifact.kind==='system'" @click="openSystem(artifact)">Open in system design</button></div><div class="config-canvas"><VueFlow :key="artifact.symbol+'-'+compiledStamp" :nodes="graph.nodes" :edges="graph.edges" fit-view-on-init :nodes-connectable="false" @node-click="selectNode($event.node)" @node-drag-stop="moveNode"><Background/><Controls/></VueFlow><p v-if="!graph.nodes.length" class="canvas-empty">No internal nodes. Edit artifact properties or add declarations in source.</p><aside v-if="inspectorOpen" class="config-inspector"><h3>{{chosen?.label||'Artifact properties'}}</h3><button v-if="extractableNodes.some(n=>n.id===node)" :disabled="!!busy" @click="openCreation('extract')">Extract primitive…</button><label v-for="p in properties" :key="p.path">{{p.path}}<input v-if="p.type==='boolean'" type="checkbox" :checked="p.value as boolean" :disabled="!!busy" @change="patch(fieldPath(p.path),fieldValue($event,p.type))"/><input v-else :type="p.type==='number'?'number':'text'" :value="p.value" :disabled="!!busy" @change="patch(fieldPath(p.path),fieldValue($event,p.type))"/></label><p>Values supplied by shared fixtures are edited at their source. Structural fields are available through typed source suggestions.</p></aside></div></template><p v-else>Add an artifact in source or load the inspection project.</p></template>
   <template v-else-if="view==='Testbench'"><div class="testbench-heading"><h3>{{currentComponent?.body.name||'Project'}} · Testbench</h3><p class="muted">{{selectedTests.length}} direct experiments at this level. Child testbenches stay with their components.</p><div class="source-actions"><button v-for="t in selectedTests" :key="t.name" @click="go(t.origin)">Edit {{t.name.split('.').at(-1)}}</button><button v-if="!selectedTests.length&&currentComponent&&currentComponent.kind!=='definition'" :disabled="!!busy" @click="createTestbench(selected,chain)">Add testbench</button><label><input v-model="includeChildren" type="checkbox"/>Include subcomponents and aspects</label><button :disabled="!!busy||!currentComponent" @click="run()">Run component tests</button><button :disabled="!!busy" @click="run(true)">Run all tests</button></div></div><p v-if="!report">Run the testbench to inspect independently specified expectations.</p><template v-else><p :class="report.passed?'config-success':'config-error'">{{report.passed?'Passed':'Failed'}} · {{report.cases.length}} experiments · {{report.scope?'Component scope: '+report.scope.target.id+(report.scope.descendants?' + descendants':''):'Entire project'}}</p><p v-if="!(current&&report.sourceHash===compiled?.sourceHash)&&reportStamp!==stamp()" class="config-error">Evidence belongs to a different source snapshot. Run the current draft again.</p><details v-for="c in report.cases" :key="c.name" :open="!c.passed"><summary>{{c.passed?'✓':'!'}} {{c.name}}</summary><p v-if="c.error" class="config-error">{{c.error}}</p><div class="config-table"><table><thead><tr><th>Expectation</th><th>Expected</th><th>Observed</th><th>Result</th></tr></thead><tbody><tr v-for="a in c.assertions" :key="a.path"><td>{{a.path}}</td><td><code>{{JSON.stringify(a.expected)}}</code></td><td><code>{{a.observed?JSON.stringify(a.actual):'Missing observation'}}</code></td><td>{{a.passed?'Pass':'Fail'}}</td></tr></tbody></table></div><details><summary>Execution trace and state</summary><pre>{{JSON.stringify(c.result,null,2)}}</pre></details></details></template></template>
   <template v-else-if="view==='Packages'"><div class="package-identity"><label>Package ID<input v-model="packageID"/></label><label>Version<input v-model="packageVersion"/></label><button :disabled="!!busy" @click="pack">Build package</button><button :disabled="!!busy" @click="action('Loading installed packages',listReleases)">Installed packages</button></div><template v-if="release"><h3>{{release.id}} @ {{release.version}}</h3><p v-if="current&&release.project.lock&&JSON.stringify(release.project.files)!==JSON.stringify(project.files)" class="config-error">This package belongs to an earlier source snapshot. Build a new package to include current edits.</p><code class="wrap">{{release.digest}}</code><p>{{release.report?(release.report.passed?'Tests passed':'Tests failed'):'No test evidence'}} · {{release.artifacts.length}} exact artifacts. Systems and deployment models are included in the portable package.</p><div class="package-actions"><button @click="download(release.id+'-'+release.version+'.json',release)">Export package</button><button :disabled="!!busy" @click="install">Install atomically</button><button :disabled="!!busy||!release.report" @click="replay">Replay evidence</button><button :disabled="!!busy" @click="previousUpload?.click()">Compare previous package</button></div></template><details v-if="comparison" open><summary>Compatibility review · {{comparison.compatible?'compatible':'review needed'}}</summary><p v-for="(c,i) in comparison.changes" :key="i">{{c.kind}} · {{c.id}} · {{c.status}}<br/>{{c.detail}}</p></details><button v-for="r in releases" :key="r.id+r.version" class="installed-release" :disabled="!!busy" @click="openRelease(r.id,r.version)">{{r.id}} @ {{r.version}}</button><p class="muted">Installation is one PostgreSQL transaction. Existing versions are immutable. Source packages describe the supported offline engines; live deployment requires the later runtime implementation.</p></template>
   <div v-if="compiled&&!compiled.valid&&compiledStamp===stamp()" class="config-diagnostics" role="alert"><h3>Fix configuration</h3><button v-for="(d,i) in compiled.diagnostics" :key="i" @click="go(d)">{{d.file}}:{{d.line}}:{{d.column}} · {{d.code}} · {{d.path}} — {{d.message}}</button></div>
  </main>
 </div>
 <input ref="folderUpload" type="file" webkitdirectory multiple hidden @change="importFile($event)"/><input ref="upload" type="file" accept=".json,.lce" multiple hidden @change="importFile($event)"/><input ref="previousUpload" type="file" accept=".json" hidden @change="importFile($event,true)"/>
</section>
</template>
